package com.campus.registration.repository; import com.campus.registration.model.*;import java.sql.*;import java.util.*; public class RegistrationRepository{final Database db;public RegistrationRepository(Database d){db=d;}public boolean registered(String st,String co)throws SQLException{try(var c=db.connect();var p=c.prepareStatement("SELECT 1 FROM registrations WHERE student=? AND course=?")){p.setString(1,st);p.setString(2,co);return p.executeQuery().next();}}public int count(String co)throws SQLException{try(var c=db.connect();var p=c.prepareStatement("SELECT COUNT(*) FROM registrations WHERE course=?")){p.setString(1,co);try(var r=p.executeQuery()){return r.next()?r.getInt(1):0;}}}public void save(String st,String co,String sec)throws SQLException{try(var c=db.connect();var p=c.prepareStatement("INSERT INTO registrations VALUES(?,?,?)")){p.setString(1,st);p.setString(2,co);p.setString(3,sec);p.executeUpdate();}}public List<Section> timetable(String st)throws SQLException{List<Section>a=new ArrayList<>();try(var c=db.connect();var p=c.prepareStatement("SELECT s.course,s.section,s.day,s.start,s.end,s.room FROM registrations r JOIN sections s ON r.course=s.course AND r.section=s.section WHERE r.student=?")){p.setString(1,st);try(var r=p.executeQuery()){while(r.next())a.add(new Section(r.getString(1),r.getString(2),r.getString(3),r.getInt(4),r.getInt(5),r.getString(6)));}}return a;}public void logClash(String st,String co,String m)throws SQLException{try(var c=db.connect();var p=c.prepareStatement("INSERT INTO clash_logs(student,course,message) VALUES(?,?,?)")){p.setString(1,st);p.setString(2,co);p.setString(3,m);p.executeUpdate();}}public List<String> clashLogs()throws SQLException{List<String>a=new ArrayList<>();try(var c=db.connect();var s=c.createStatement();var r=s.executeQuery("SELECT student||' | '||course||' | '||message FROM clash_logs ORDER BY created_at DESC")){while(r.next())a.add(r.getString(1));}return a;}}